    fixed:["The same magnet","Held just above the thing"],
    table:{"clip":{sticks:true,short:"Sticks",obs:"The paperclip jumps up and sticks to the magnet."},
           "peg":{sticks:false,short:"Does not stick",obs:"The wooden peg stays on the sand."},
           "button":{sticks:false,short:"Does not stick",obs:"The plastic button stays on the sand."},
           "cap":{sticks:true,short:"Sticks",obs:"The steel bottle top sticks to the magnet."}},
