MISSIONS.push(...MORE_MISSIONS);
MISSIONS.sort((a,b)=>a.g-b.g);
{ const k = {}; MISSIONS.forEach(m => { k[m.g] = (k[m.g]||0)+1; m.k = k[m.g]; m.n = `${m.g}.${m.k}`; }); }

/* Second New problem question: which idea applies. Both questions must be right, with no hints, for Demonstrated. */
MISSIONS.forEach(m => {
  const others = MISSIONS.filter(o => o.g===m.g && o!==m), a = others[m.k % others.length], b = others[(m.k+4) % others.length];
  m.transfer.qs.push({q:"Which idea from this mission helped you solve it?", idea:true,
    opts:[[m.idea,1,"Yes. The idea you tested in this mission works here too."],
          [a.idea,0,`That idea comes from "${a.title}". Which idea did you test here?`],
          [b.idea,0,`That idea comes from "${b.title}". Which idea did you test here?`]],
    hints:["Think back to the test you ran in this mission.","Which sentence matches what your test showed?",`This mission was "${m.title}", about ${m.concept.toLowerCase()}.`]});
});

